import json, os, re
base='/home/ubuntu/runs/paper/glm-hpl-u1-turns/play/users/u000/system/state/workspace/programs/task-bb30ebc2'
d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n')
pairs=json.load(open(base+'.json'))
# parse demo pairs from this session's log
for m in re.finditer(r'Demo pair \d+ (input|output) \((\d+)x(\d+)\):\n',t):
    pass
found={}
for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
    k,h,w=m[1],int(m[2]),int(m[3])
    rows=[[int(x) for x in r.split()] for r in t[m.end():].split('\n')[:h]]
    if all(len(r)==w for r in rows): found.setdefault(k,rows)
inputs=[k for k in found if k.startswith('Demo pair') and k.endswith('input')]
for k in inputs:
    outk=k.replace('input','output')
    if outk in found:
        p={"input":found[k],"output":found[outk]}
        if p not in pairs: pairs.append(p)
json.dump(pairs, open(base+'.json','w'))
# memory via harness
rlm.harness.create_memory(name='task-bb30ebc2', content=json.dumps({
 "task":"task-bb30ebc2",
 "files":[base+'.py',base+'.json'],
 "program_reproduces_all_pairs":True,
 "note":"identify block color (most common), line color, special rows/cols lacking block color; output = colors at intersections of special rows/cols if uniform"}), global_=True)
print(len(pairs), 'pairs saved')

try:
    rlm.harness.update_memory('task_bb30ebc2', content=json.dumps({
     "task":"task-bb30ebc2",
     "files":[base+'.py',base+'.json'],
     "program_reproduces_all_pairs":True,
     "note":"identify block color (most common), line color, special rows/cols lacking block color; output = colors at intersections of special rows/cols if uniform"}), global_=True)
    print('updated')
except Exception as e:
    print('ERR', e)
